insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('da59eb1c-94cf-5eff-8faa-01bcd1bd7fab', 'Sé da Arquidiocese da Paraíba. Horário de domingo apurado pela imprensa local; a paróquia pede confirmação.', '{"https://paraibabusiness.com.br/missas-deste-domingo-25-em-joao-pessoa-horarios-e-como-conciliar-com-a-votacao/","https://paraibabusiness.com.br/vai-a-missa-neste-domingo-confira-os-horarios-em-igrejas-de-joao-pessoa/","https://arquidiocesepb.org.br/comunicacoes-16/"}', 'media'),
  ('59f7c455-1efd-5e37-91ed-ed874ce5a6b9', 'Sem horário de missa publicado nas fontes consultadas em novembro de 2026. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesepb.org.br/comunicacoes-16/","https://arquidiocesepb.org.br/missas-online-arcebispo-e-padres-mantem-celebracoes-em-tempo-de-quarentena/"}', 'alta'),
  ('fea6e080-9297-5a8c-8c40-7319f3d29f7a', 'Sem horário de missa publicado nas fontes consultadas em novembro de 2026.', '{"https://arquidiocesepb.org.br/arquidiocese-da-paraiba-celebra-a-festa-de-nossa-senhora-da-conceicao-com-programacao-especial-em-13-paroquias-e-no-seminario-arquidiocesano/","https://arquidiocesepb.org.br/nomeacoes-transferencias-e-outras-comunicacoes/"}', 'alta'),
  ('13ff0e01-57eb-5bdb-bfac-1bedf8c9ec16', 'Santuário arquidiocesano com reitor próprio. Sede da Romaria da Penha, em outubro e novembro.', '{"https://arquidiocesepb.org.br/comunicado-19/","https://paraibabusiness.com.br/missas-deste-domingo-em-joao-pessoa-confira-horarios-igrejas-e-perfis-oficiais-das-paroquias/"}', 'alta'),
  ('9732618b-a2fa-54cc-b377-27f44c25c23e', 'Sem horário de missa publicado nas fontes consultadas em novembro de 2026.', '{"https://arquidiocesepb.org.br/arquidiocese-da-paraiba-celebra-a-festa-de-nossa-senhora-da-conceicao-com-programacao-especial-em-13-paroquias-e-no-seminario-arquidiocesano/"}', 'alta'),
