  ('0ef00cbe-a22a-58d5-bebe-5cc45592e04e', 'Horário de domingo apurado pela imprensa local; a paróquia pede confirmação. Ponto no mapa aproximado: centro da cidade.', '{"https://paraibabusiness.com.br/horarios-de-missas-em-joao-pessoa-neste-domingo-1o-veja-programacao/","https://arquidiocesepb.org.br/comunicacoes-16/"}', 'media'),
  ('1f2fe9b5-cee4-548b-86ce-89ffc2c97e3e', 'Horário de domingo apurado pela imprensa local; a paróquia pede confirmação. Ponto no mapa aproximado: centro da cidade.', '{"https://paraibabusiness.com.br/missas-deste-domingo-em-joao-pessoa-confira-horarios-igrejas-e-perfis-oficiais-das-paroquias/","https://arquidiocesepb.org.br/comunicacoes-16/"}', 'media'),
  ('d5b550d0-e3eb-599a-ab4a-3eb34c6e376f', 'Criada em 13/12/2024, desmembrada da Paróquia Santuário São Judas Tadeu. Sem horário de missa publicado nas fontes consultadas em novembro de 2026. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesepb.org.br/nova-paroquia-na-arquidiocese-da-paraiba-convite-para-a-celebracao-de-instituicao-da-paroquia-nossa-senhora-da-esperanca-e-posse-do-mons-ednaldo-araujo/","https://arquidiocesepb.org.br/comunicacoes-16/"}', 'alta'),
